-- Load the Oct 23 seed CSVs and hd_parts_reference into the one parts store. GENERATED by
-- scripts/build-seed-reference-sql.ts on 2026-10-29 from the live tables. Every item that does
-- not load as-is - recovered, matched or still held, with the reason - is in
-- scripts/load-seed-and-reference-report.txt.
--
-- ENDS IN ROLLBACK. Read the summary table it prints, then change the last line to
-- COMMIT to keep it. Any check that fails raises an error and nothing is applied.
--
-- store before: 985 parts, 2586 fitment, 7 supersessions, 18 crosses, 0 engines
-- adds: 277 parts (A 28, B 249), 787 fitment (A 759, B 28), 28 supersessions, 227 crosses (A 154, B 73), 32 engines
-- crosses by brand: Fleetguard 26, Baldwin 23, WIX 22, Hitachi 20, Dayco 20, NAPA 18, Delco Remy 17, Carquest 17, Luber-finer 15, NAPA Gold 15, Continental 13, Denso 12, Donaldson 9
--
-- Trust: verified = false on every row. Source A carries its own confidence; fitment
-- carried from a superseded number is 'derived'; Source B carries none.
-- Not carried: source notes, source_url, unit_series / unit_group / engine_family.
-- Store rows touched, and only these: 3 part numbers given their zero back (step 0a) and
-- 18 fitment rows given the other side of a changeover break (step 0b). No part type changes.
-- Changeovers dated:
--   11-7400 serial before L32014  ->  11-9300 serial from L32014  (11 models)
--   11-7382 serial before L32014  ->  11-9182 serial from L32014  (11 models)
--   11-7400 build date before 2001-01-01  ->  11-9300 build date from 2001-01-01  (9 models)

BEGIN;

CREATE TEMP TABLE _ld_before ON COMMIT DROP AS
SELECT (SELECT count(*) FROM public.parts) AS parts, (SELECT count(*) FROM public.part_fitment) AS part_fitment,
       (SELECT count(*) FROM public.part_supersession) AS part_supersession, (SELECT count(*) FROM public.part_cross_reference) AS part_cross_reference,
       (SELECT count(*) FROM public.engines) AS engines;

-- 0a. Repair 3 store number(s) rule 6 now writes with their zero (TK NNN-NNN -> NNN-0NNN).
-- 0b. Give 18 existing store fitment row(s) the other side of a changeover break.
--     Each row is named by id and must still have no break, or nothing is applied.
DO $$
DECLARE n INTEGER;
BEGIN
  IF (SELECT count(*) FROM public.parts WHERE (id, part_number) IN (('227096aa-a1d4-4490-8cdf-01628c08777c'::uuid, '203-799'), ('a1ca46e7-35d6-4d13-8e58-be5477595998'::uuid, '306-221'), ('a2973953-d85f-4139-ab85-a4b0f75315ea'::uuid, '107-349'))) <> 3 THEN
    RAISE EXCEPTION 'repair: a store number is not what this file was built against'; END IF;
  UPDATE public.parts SET part_number = '203-0799', updated_at = now() WHERE id = '227096aa-a1d4-4490-8cdf-01628c08777c' AND part_number = '203-799';
  UPDATE public.parts SET part_number = '306-0221', updated_at = now() WHERE id = 'a1ca46e7-35d6-4d13-8e58-be5477595998' AND part_number = '306-221';
  UPDATE public.parts SET part_number = '107-0349', updated_at = now() WHERE id = 'a2973953-d85f-4139-ab85-a4b0f75315ea' AND part_number = '107-349';
  IF (SELECT count(*) FROM public.parts WHERE (id, part_number) IN (('227096aa-a1d4-4490-8cdf-01628c08777c'::uuid, '203-0799'), ('a1ca46e7-35d6-4d13-8e58-be5477595998'::uuid, '306-0221'), ('a2973953-d85f-4139-ab85-a4b0f75315ea'::uuid, '107-0349'))) <> 3 THEN
    RAISE EXCEPTION 'repair: not every number was restored'; END IF;
  IF (SELECT count(*) FROM public.part_fitment WHERE id IN ('10906421-4bdf-42d1-a94f-c1c141949a64', '11e10837-4d15-4722-b166-cfe51e87570d', '2d1d917d-9def-41b6-8fc2-0d464a5f9e09', '320d776d-6132-4000-8a8f-1c136f9829d7', '460587fd-c9f5-45da-8a48-a9274ed32cee', '4bd8a44b-181a-467b-9f72-26d119ead6cd', '4d287d84-1f8a-4e83-bc15-cef1c34a8728', '86a79206-8116-4333-9c0c-09fa2bf165df', '974aa58c-018e-4c23-8a60-64cc10103b53', 'a5aa81c3-5a57-46dc-933e-019049c4130c', 'b1322633-1590-48e4-8b17-885851d10a19', 'b5fa957c-93cf-4319-9efe-533ef034c9b4', 'cefd0505-dde5-4cc6-b194-b9f8fb6567bb', 'd1dc759f-0eaf-4aef-afb7-a5b3dccd66cc', 'dbb6d492-2a04-4f4f-9abb-2293a14c1b7c', 'dcd2091e-50cf-450a-a404-578b4e192626', 'f025a23d-9ec4-4f7c-a7ba-a7ecb1744dc8', 'f9a07b22-af39-49b7-90dc-158276ff69ec')
        AND serial_from IS NULL AND serial_before IS NULL AND build_date_from IS NULL AND build_date_before IS NULL) <> 18 THEN
    RAISE EXCEPTION 'changeover: a store fitment row is missing or already has a break'; END IF;
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = '10906421-4bdf-42d1-a94f-c1c141949a64';   -- 11-9300 SB-110
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = '11e10837-4d15-4722-b166-cfe51e87570d';   -- 11-9182 SB-310
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = '2d1d917d-9def-41b6-8fc2-0d464a5f9e09';   -- 11-9300 SB-100
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = '320d776d-6132-4000-8a8f-1c136f9829d7';   -- 11-9300 SB-300
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = '460587fd-c9f5-45da-8a48-a9274ed32cee';   -- 11-9182 SB-100
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = '4bd8a44b-181a-467b-9f72-26d119ead6cd';   -- 11-9300 SB-200
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = '4d287d84-1f8a-4e83-bc15-cef1c34a8728';   -- 11-9182 SB-200
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = '86a79206-8116-4333-9c0c-09fa2bf165df';   -- 11-9182 SB-300
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = '974aa58c-018e-4c23-8a60-64cc10103b53';   -- 11-9182 Spectrum SB
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = 'a5aa81c3-5a57-46dc-933e-019049c4130c';   -- 11-9300 SB-190
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = 'b1322633-1590-48e4-8b17-885851d10a19';   -- 11-9300 Spectrum SB
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = 'b5fa957c-93cf-4319-9efe-533ef034c9b4';   -- 11-9300 SB-210
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = 'cefd0505-dde5-4cc6-b194-b9f8fb6567bb';   -- 11-9300 SB-310
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = 'd1dc759f-0eaf-4aef-afb7-a5b3dccd66cc';   -- 11-9182 SB-110
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = 'dbb6d492-2a04-4f4f-9abb-2293a14c1b7c';   -- 11-9182 SB-400
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = 'dcd2091e-50cf-450a-a404-578b4e192626';   -- 11-9182 SB-190
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = 'f025a23d-9ec4-4f7c-a7ba-a7ecb1744dc8';   -- 11-9182 SB-210
  UPDATE public.part_fitment SET serial_from = 'L32014' WHERE id = 'f9a07b22-af39-49b7-90dc-158276ff69ec';   -- 11-9300 SB-400
  SELECT count(*) INTO n FROM public.part_fitment WHERE id IN ('10906421-4bdf-42d1-a94f-c1c141949a64', '11e10837-4d15-4722-b166-cfe51e87570d', '2d1d917d-9def-41b6-8fc2-0d464a5f9e09', '320d776d-6132-4000-8a8f-1c136f9829d7', '460587fd-c9f5-45da-8a48-a9274ed32cee', '4bd8a44b-181a-467b-9f72-26d119ead6cd', '4d287d84-1f8a-4e83-bc15-cef1c34a8728', '86a79206-8116-4333-9c0c-09fa2bf165df', '974aa58c-018e-4c23-8a60-64cc10103b53', 'a5aa81c3-5a57-46dc-933e-019049c4130c', 'b1322633-1590-48e4-8b17-885851d10a19', 'b5fa957c-93cf-4319-9efe-533ef034c9b4', 'cefd0505-dde5-4cc6-b194-b9f8fb6567bb', 'd1dc759f-0eaf-4aef-afb7-a5b3dccd66cc', 'dbb6d492-2a04-4f4f-9abb-2293a14c1b7c', 'dcd2091e-50cf-450a-a404-578b4e192626', 'f025a23d-9ec4-4f7c-a7ba-a7ecb1744dc8', 'f9a07b22-af39-49b7-90dc-158276ff69ec')
    AND (serial_from IS NOT NULL OR serial_before IS NOT NULL OR build_date_from IS NOT NULL OR build_date_before IS NOT NULL);
  IF n <> 18 THEN RAISE EXCEPTION 'changeover: % of 18 store rows got their break', n; END IF;
  NULL;
END $$;

CREATE TEMP TABLE _ld_engines (engine_code TEXT, engine_maker TEXT, base_engine TEXT, tier TEXT, confidence TEXT) ON COMMIT DROP;

CREATE TEMP TABLE _ld_parts (src TEXT, manufacturer TEXT, part_number TEXT, part_type TEXT, description TEXT, equipment_type TEXT) ON COMMIT DROP;

CREATE TEMP TABLE _ld_fitment (src TEXT, manufacturer TEXT, part_number TEXT, unit_model TEXT, engine_model TEXT, engine_code TEXT,
  match_type TEXT, serial_from TEXT, serial_before TEXT, build_date_from DATE, build_date_before DATE, tier TEXT, confidence TEXT, note TEXT) ON COMMIT DROP;

CREATE TEMP TABLE _ld_sup (manufacturer TEXT, old_number TEXT, new_number TEXT, confidence TEXT) ON COMMIT DROP;

CREATE TEMP TABLE _ld_cross (src TEXT, manufacturer TEXT, part_number TEXT, brand TEXT, brand_number TEXT, confidence TEXT) ON COMMIT DROP;

-- Checks BEFORE writing. Any failure stops everything.
DO $$
BEGIN
  IF (SELECT count(*) FROM _ld_engines) <> 32 OR (SELECT count(*) FROM _ld_parts) <> 277 OR (SELECT count(*) FROM _ld_fitment) <> 787
     OR (SELECT count(*) FROM _ld_sup) <> 28 OR (SELECT count(*) FROM _ld_cross) <> 227 THEN
    RAISE EXCEPTION 'load: staged row counts are not what the plan says'; END IF;
  IF (SELECT count(*) FROM public.parts) <> 985 OR (SELECT count(*) FROM public.part_fitment) <> 2586
     OR (SELECT count(*) FROM public.part_supersession) <> 7 OR (SELECT count(*) FROM public.part_cross_reference) <> 18
     OR (SELECT count(*) FROM public.engines) <> 0 THEN
    RAISE EXCEPTION 'load: the store is not the size this file was built against - rebuild it'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_engines e JOIN public.engines x ON x.engine_code = e.engine_code) THEN
    RAISE EXCEPTION 'load: an engine is already in the store'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_parts f JOIN public.parts p
             ON p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number)) THEN
    RAISE EXCEPTION 'load: a new part is already in the store'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_parts GROUP BY manufacturer, public.normalize_part_number(part_number) HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'load: a new part is staged twice'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_parts WHERE part_number LIKE '37-%') THEN RAISE EXCEPTION 'load: a 37- number'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_parts WHERE (manufacturer = 'Thermo King' AND part_number !~ '^[0-9]{2,3}-[0-9]{4}$')
             OR (manufacturer = 'Carrier Transicold' AND part_number !~ '^[0-9]{2}-[0-9]{5}-[0-9]{2}$')
             OR manufacturer NOT IN ('Thermo King', 'Carrier Transicold')) THEN
    RAISE EXCEPTION 'load: a number is missing a zero, carries a marker, or does not fit the maker shape'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_parts WHERE description ~* 'napa|reilly|autozone|advance auto|rockauto|fleetpride|amazon|ebay|mincarone|walmart|carquest|swisclima|kingreat|fuerdun|www\.|https?:')
  OR EXISTS (SELECT 1 FROM _ld_parts WHERE part_type ~* 'napa|reilly|autozone|amazon|ebay|mincarone|carquest|swisclima|kingreat|fuerdun')
  OR EXISTS (SELECT 1 FROM _ld_fitment WHERE note ~* 'napa|reilly|autozone|amazon|ebay|mincarone|carquest|swisclima|kingreat|fuerdun|www\.|https?:') THEN
    RAISE EXCEPTION 'load: a vendor or retailer name outside a cross brand'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_fitment WHERE NOT public.is_single_model(unit_model) OR NOT public.is_single_model(engine_model)) THEN
    RAISE EXCEPTION 'load: a fitment model is a group'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_fitment f WHERE f.engine_code IS NOT NULL
             AND NOT EXISTS (SELECT 1 FROM public.engines x WHERE x.engine_code = f.engine_code)
             AND NOT EXISTS (SELECT 1 FROM _ld_engines x WHERE x.engine_code = f.engine_code)) THEN
    RAISE EXCEPTION 'load: a fitment engine code is not an engine'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_fitment f WHERE NOT EXISTS (SELECT 1 FROM _ld_parts n WHERE n.manufacturer = f.manufacturer AND n.part_number = f.part_number)
             AND NOT EXISTS (SELECT 1 FROM public.parts p WHERE p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number))) THEN
    RAISE EXCEPTION 'load: a fitment row names no part'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_cross f WHERE NOT EXISTS (SELECT 1 FROM _ld_parts n WHERE n.manufacturer = f.manufacturer AND n.part_number = f.part_number)
             AND NOT EXISTS (SELECT 1 FROM public.parts p WHERE p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number))) THEN
    RAISE EXCEPTION 'load: a cross names no part'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_fitment f JOIN public.parts p
             ON p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number)
             JOIN public.part_fitment x ON x.part_id = p.id
              AND upper(coalesce(x.unit_model, '')) = upper(coalesce(f.unit_model, ''))
              AND upper(coalesce(x.engine_model, '')) = upper(coalesce(f.engine_model, ''))
              AND upper(coalesce(x.engine_code, '')) = upper(coalesce(f.engine_code, ''))) THEN
    RAISE EXCEPTION 'load: a fitment row is already in the store'; END IF;
  -- No fitment onto a retired number: one the store retires, or a confirmed / oem_matrix link here retires.
  IF EXISTS (SELECT 1 FROM _ld_fitment f JOIN public.part_supersession s
             ON s.manufacturer = f.manufacturer AND s.old_number_normalized = public.normalize_part_number(f.part_number))
  OR EXISTS (SELECT 1 FROM _ld_fitment f JOIN _ld_sup s
             ON s.manufacturer = f.manufacturer AND public.normalize_part_number(s.old_number) = public.normalize_part_number(f.part_number)
             AND s.confidence IN ('confirmed', 'oem_matrix')) THEN
    RAISE EXCEPTION 'load: fitment onto a superseded number'; END IF;
  -- No fitment that straddles a split: an unconditional row beside a serial / build-date
  -- split for the same maker + model + part type on another part, or the reverse.
  IF EXISTS (
    WITH staged AS (
      SELECT f.manufacturer, upper(regexp_replace(f.unit_model, '[^A-Za-z0-9]', '', 'g')) AS model,
             CASE WHEN coalesce(p.part_type, n.part_type) ~* '^filter - oil' THEN CASE WHEN coalesce(coalesce(p.description, n.description), '') ~* 'bypass' THEN 'oil-bypass' ELSE 'oil' END WHEN coalesce(p.part_type, n.part_type) ~* '^filter - fuel' THEN CASE WHEN coalesce(coalesce(p.description, n.description), '') ~* 'pre-filter|strainer' THEN 'fuel-pre' WHEN coalesce(coalesce(p.description, n.description), '') ~* 'secondary' THEN 'fuel-secondary' WHEN coalesce(coalesce(p.description, n.description), '') ~* 'primary' THEN 'fuel-primary' WHEN coalesce(coalesce(p.description, n.description), '') ~* 'davco|heater' THEN 'fuel-heater' ELSE 'fuel' END WHEN coalesce(p.part_type, n.part_type) ~* '^filter - (cab )?air' THEN CASE WHEN coalesce(p.part_type, n.part_type) ~* 'cab' OR coalesce(coalesce(p.description, n.description), '') ~* 'cab|evaporator' THEN 'air-cab' ELSE 'air' END ELSE coalesce(p.part_type, n.part_type) END AS part_type, public.normalize_part_number(f.part_number) AS pn,
             (f.serial_from IS NOT NULL OR f.serial_before IS NOT NULL OR f.build_date_from IS NOT NULL OR f.build_date_before IS NOT NULL) AS split
        FROM _ld_fitment f
        LEFT JOIN public.parts p ON p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number)
        LEFT JOIN _ld_parts n ON n.manufacturer = f.manufacturer AND n.part_number = f.part_number
       WHERE f.unit_model IS NOT NULL),
    existing AS (
      SELECT p.manufacturer, upper(regexp_replace(x.unit_model, '[^A-Za-z0-9]', '', 'g')) AS model, CASE WHEN p.part_type ~* '^filter - oil' THEN CASE WHEN coalesce(p.description, '') ~* 'bypass' THEN 'oil-bypass' ELSE 'oil' END WHEN p.part_type ~* '^filter - fuel' THEN CASE WHEN coalesce(p.description, '') ~* 'pre-filter|strainer' THEN 'fuel-pre' WHEN coalesce(p.description, '') ~* 'secondary' THEN 'fuel-secondary' WHEN coalesce(p.description, '') ~* 'primary' THEN 'fuel-primary' WHEN coalesce(p.description, '') ~* 'davco|heater' THEN 'fuel-heater' ELSE 'fuel' END WHEN p.part_type ~* '^filter - (cab )?air' THEN CASE WHEN p.part_type ~* 'cab' OR coalesce(p.description, '') ~* 'cab|evaporator' THEN 'air-cab' ELSE 'air' END ELSE p.part_type END AS part_type, p.part_number_normalized AS pn,
             (x.serial_from IS NOT NULL OR x.serial_before IS NOT NULL OR x.build_date_from IS NOT NULL OR x.build_date_before IS NOT NULL) AS split
        FROM public.part_fitment x JOIN public.parts p ON p.id = x.part_id WHERE x.unit_model IS NOT NULL),
    every AS (SELECT * FROM staged UNION ALL SELECT * FROM existing)
    SELECT 1 FROM staged s JOIN every e ON e.manufacturer = s.manufacturer AND e.model = s.model AND e.part_type = s.part_type
     WHERE e.pn <> s.pn AND e.split <> s.split) THEN
    RAISE EXCEPTION 'load: a fitment row straddles a serial or build-date split'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_sup s JOIN public.part_supersession x ON x.manufacturer = s.manufacturer
             AND x.old_number_normalized = public.normalize_part_number(s.old_number) AND x.new_number_normalized = public.normalize_part_number(s.new_number)) THEN
    RAISE EXCEPTION 'load: a supersession is already in the store'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_cross c JOIN public.parts p
             ON p.manufacturer = c.manufacturer AND p.part_number_normalized = public.normalize_part_number(c.part_number)
             JOIN public.part_cross_reference x ON x.part_id = p.id AND upper(x.brand) = upper(c.brand)
              AND x.brand_number_normalized = public.normalize_part_number(c.brand_number)) THEN
    RAISE EXCEPTION 'load: a cross is already in the store'; END IF;
  IF EXISTS (SELECT 1 FROM _ld_cross GROUP BY manufacturer, public.normalize_part_number(part_number), upper(brand), public.normalize_part_number(brand_number) HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'load: a cross is staged twice'; END IF;
END $$;

-- 1. engines (fitment rows name them)
SELECT engine_code, engine_maker, base_engine, tier, confidence, NULL FROM _ld_engines;

-- 2. parts: Source A then Source B
SELECT manufacturer, part_number, part_type, description, NULL, FALSE, src, NULL, equipment_type FROM _ld_parts;

-- 3. fitment
                                 build_date_from, build_date_before, tier, note, verified, source, confidence)
SELECT p.id, f.unit_model, f.engine_model, f.engine_code, f.match_type, f.serial_from, f.serial_before,
       f.build_date_from, f.build_date_before, f.tier, f.note, FALSE, f.src, f.confidence
  FROM _ld_fitment f
  JOIN public.parts p ON p.manufacturer = f.manufacturer AND p.part_number_normalized = public.normalize_part_number(f.part_number);

-- 4. supersessions (Source A)
SELECT manufacturer, old_number, new_number, NULL, FALSE, 'nwi-seed-2026-10-23', confidence FROM _ld_sup;

-- 5. crosses (every brand, retailer house brands included)
SELECT p.id, c.brand, c.brand_number, FALSE, c.src, c.confidence
  FROM _ld_cross c
  JOIN public.parts p ON p.manufacturer = c.manufacturer AND p.part_number_normalized = public.normalize_part_number(c.part_number);

-- Checks AFTER writing: every table moved by exactly the planned amount, nothing else.
DO $$
DECLARE b RECORD;
BEGIN
  SELECT * INTO b FROM _ld_before;
  IF (SELECT count(*) FROM public.engines) - b.engines <> 32 THEN RAISE EXCEPTION 'load: engines did not grow by 32'; END IF;
  IF (SELECT count(*) FROM public.parts) - b.parts <> 277 THEN RAISE EXCEPTION 'load: parts did not grow by 277'; END IF;
  IF (SELECT count(*) FROM public.part_fitment) - b.part_fitment <> 787 THEN RAISE EXCEPTION 'load: part_fitment did not grow by 787'; END IF;
  IF (SELECT count(*) FROM public.part_supersession) - b.part_supersession <> 28 THEN RAISE EXCEPTION 'load: part_supersession did not grow by 28'; END IF;
  IF (SELECT count(*) FROM public.part_cross_reference) - b.part_cross_reference <> 227 THEN RAISE EXCEPTION 'load: part_cross_reference did not grow by 227'; END IF;
  IF (SELECT count(*) FROM public.parts WHERE source = 'nwi-seed-2026-10-23') <> 28 OR (SELECT count(*) FROM public.parts WHERE source = 'nwi-hd-parts-reference-112') <> 249 THEN
    RAISE EXCEPTION 'load: parts per source are not what the plan says'; END IF;
  IF EXISTS (SELECT 1 FROM public.parts WHERE source IN ('nwi-seed-2026-10-23', 'nwi-hd-parts-reference-112') AND (verified OR confidence IS NOT NULL OR notes IS NOT NULL)) THEN
    RAISE EXCEPTION 'load: a new part is not verified=false / confidence NULL / notes NULL'; END IF;
  IF EXISTS (SELECT 1 FROM public.part_fitment WHERE source IN ('nwi-seed-2026-10-23', 'nwi-hd-parts-reference-112') AND verified)
  OR EXISTS (SELECT 1 FROM public.part_cross_reference WHERE source IN ('nwi-seed-2026-10-23', 'nwi-hd-parts-reference-112') AND verified)
  OR EXISTS (SELECT 1 FROM public.part_supersession WHERE source = 'nwi-seed-2026-10-23' AND (verified OR note IS NOT NULL)) THEN
    RAISE EXCEPTION 'load: a new row is marked verified'; END IF;
  IF EXISTS (SELECT 1 FROM public.part_fitment WHERE source = 'nwi-hd-parts-reference-112' AND confidence IS NOT NULL) THEN
    RAISE EXCEPTION 'load: a Source B fitment row carries a trust tier'; END IF;
END $$;

-- What it did (this is the table the SQL editor shows).
SELECT 'parts' AS table_name, b.parts AS before, (SELECT count(*) FROM public.parts) AS after, 277 AS planned FROM _ld_before b
UNION ALL SELECT 'part_fitment', b.part_fitment, (SELECT count(*) FROM public.part_fitment), 787 FROM _ld_before b
UNION ALL SELECT 'part_supersession', b.part_supersession, (SELECT count(*) FROM public.part_supersession), 28 FROM _ld_before b
UNION ALL SELECT 'part_cross_reference', b.part_cross_reference, (SELECT count(*) FROM public.part_cross_reference), 227 FROM _ld_before b
UNION ALL SELECT 'engines', b.engines, (SELECT count(*) FROM public.engines), 32 FROM _ld_before b
UNION ALL SELECT 'store numbers given their zero back', 0, (SELECT count(*) FROM public.parts WHERE (id, part_number) IN (('227096aa-a1d4-4490-8cdf-01628c08777c'::uuid, '203-0799'), ('a1ca46e7-35d6-4d13-8e58-be5477595998'::uuid, '306-0221'), ('a2973953-d85f-4139-ab85-a4b0f75315ea'::uuid, '107-0349'))), 3 FROM _ld_before b
